; >S:BOMB-CODE; PUT "BOMB-CODE";;; ALL THE TIME-BOMB STUFF;BOMB;; THE TIME-BOMB WILL WORK AS; FOLLOWS :-;; 1> FIRE BUTTON DROPS A BOMB;    & SETS UP A TIMER;; 2> TIMER COUNTS DOWN;; 3> A RUSTIC FILL;LDA BOMBON  ;* BOMB ALREADY ON ?BNE BM1;LDA BREADY  ;* BOMB RECHARGED ?BEQ BM1     ;* NOT YET;LDX MANXLDY MANY;LDA DIRAND #3BEQ BERM1;INX;BERM1;LDA DIRAND #$CBEQ BERM2;INY;BERM2;STX BOMXSTY BOMY ;* TL CO-ORD;JSR XY;LDA SLSTA BOMSLSTA BOMCL;LDA SL+1STA BOMSL+1;LDA CL+1STA BOMCL+1;; GET SCREEN AND COLOUR ADDRESS;LDA #55STA TIMER   ;* COUNT DOWN;LDX #1STX BOMBON  ;* ONE'S ON NOW.;DEXSTX BOMBGO;LDA SNDFLGBEQ BM1;LDA #$2FSTA VOL;; CHAN #2,NORMAL (NOISE LATER);LDA #0STA SOU2HISTA SOU2LO;BM1;RTS;;----------------------------;UPBOMB;; CALLED UNDER INTERRUPT TO; COUNT THE TIMER DOWN & DOES; A FLAG TO TELL THE BASIC LOOP; TO DO THE EXPLOSION.;JSR READY    ;* UPDATE CHARGER;LDA BOMBONBEQ TIMOOT;; ONLY DO THIS IF THE BOMB IS ON;JSR BOMPRT  ;* PRINT IT (FLASH);DEC TIMERBEQ STBOMB  ;* LO BYTE;LDA #56SECSBC TIMER   ;* INVERSE;ASL AROL MORONASL AROL MORONASL AROL MORONASL AROL MORONSTA SOU2LO  ;* SOUND *16;LDA MORONSTA SOU2HI  ;* SOUNH HI;TIMOOT;RTS;STBOMB;LDA #1STA BOMBGO  ;* TELL BASIC TO GO!;RTS;;-------------------------------;BASBOM;; CALLED BY THE BASIC LOOP TO; DO THE WHOOPPEE EXPLOSION.;LDA BOMBGOBNE GOBOMR;RTS;GOBOMR;LDA ANTFAGBEQ GOBOMR;; WAIT FOR MAN TO BE IN A CHAR.; (SO WE HAVE NO HASSLE DETECTING);; WE ARE IN CONTROL.;LDA #$FFSTA SOU2LOSTA SOU2HI;LDA SNDFLGBEQ STEW2;LDA #$4FSTA VOL     ;* NOISE NOW;STEW2;LDX #1STX STOP    ;* NO IRQ'S;; INSERT MEGA/CODE HERE.;JSR FINDTL;; FIND THE ADDRESS OF THE TL OF; THE MAN FOR USE AFTER THE FILL; TO SEE IF HE DIED;JSR FILBMB;; DO THE BOMB FILL;SEI;LDX #31;CLBMBC;LDA #0STA $3960,XDEXBPL CLBMBC;; CLEAR CHARGE CHAR;; NOW STOP ALL BOMB STUFF.;LDA #0STA STOPSTA BOMBGOSTA BOMBONSTA BREADY ;* START CHARGESTA CHTIME ;* CHARGE TIMESTA VOL    ;* SOUND OFF;CLI;RTS;;*****************************;BOMPRT;; PRINT IT;;LDX #3;LDA #247STA CHAR;LDA TEDORA #%00001000STA BMBCOL      ;* MULTI COLOUR;SOD1;LDY YVAL2,XLDA CHARSTA (BOMSL),Y;LDA BMBCOLSTA (BOMCL),Y      ;* FLASH COLOUR;DEC CHARDEXBPL SOD1;RTS;;------------------------------;READY;; DO THE CHARGEING OF THE BOMB; SET 'BREADY' TO 1 IF OK.;LDA BREADYBEQ UPCHRG;; WHATS THE USE - ITS READY !;KWAH            ;* EXIT BRANCH;RTS;UPCHRG;DEC CHTIME      ;* TIMERBNE CHRGE;LDA #1STA BREADY;JSR COPYBM;; COPY FULL BOMB ACROSS;RTS;CHRGE;; UPDATE THE CHAR;; THE CHARS THAT ARE USED AS THE; RECHARGING BOMB ARE;; $2C,$2D; $2E,$2F;LDA CHTIMEAND #$0FBNE KWAH       ;* WAIT FOR TOP;              ;* BIT TO CHANGE;; NOW SCROLL CHAR UP TO MAKE; ROOM FOR NEW DATA;LDA $3970PHALDA $3978PHA;LDX #0;SCROL;LDA $3961,XSTA $3960,X;LDA $3969,XSTA $3968,X;LDA $3971,XSTA $3970,X;LDA $3979,XSTA $3978,X;INXCPX #7BNE SCROL;PLASTA $396F;PLASTA $3967;LDA CHTIME     ;* $FF - $00;LSR ALSR ALSR ALSR A;; 0-15;EOR #$0F;TAY;AND #8BEQ BOTBMB    ;* DOING TOP 2;TYAAND #7CLC           ;* X = 0 TO 7ADC #16TAY;BOTBMB;TYA;; Y HOLDS OFFSET TO CHAR DATA;LDA $3FA0,YSTA $3977     ;* LEFT CHAR;LDA $3FA0+8,YSTA $397F     ;* RIGHT CHAR;RTS;;;;;;.END